#pragma once
#include <cstdint>
namespace kstation {
class TransposeCheckTask final {
public:enum class Stage:uint8_t {ReadCurrent,ReadPrevious,Compare,Select,Return,AwaitChild,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaitingChild()const{return stage_==Stage::AwaitChild;}bool resume(){if(!awaitingChild())return false;stage_=Stage::Complete;return true;}template<class R>bool advance(R&&r){switch(stage_){case Stage::ReadCurrent:current_=r(false);stage_=Stage::ReadPrevious;break;case Stage::ReadPrevious:previous_=r(true);stage_=Stage::Compare;break;case Stage::Compare:stage_=Stage::Select;break;case Stage::Select:stage_=current_==previous_?Stage::Return:Stage::AwaitChild;break;case Stage::Return:stage_=Stage::Complete;break;case Stage::AwaitChild:case Stage::Complete:return false;}return true;}private:Stage stage_=Stage::ReadCurrent;uint8_t current_=0,previous_=0;
};
class TransposeResetTask final {
public:enum class Stage:uint8_t {ClearHeld,BindPart,Release,AllNotesOff,Return,AwaitChild,Complete};enum class Child:uint8_t {ClearHeld,Release,AllNotesOff};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaitingChild()const{return stage_==Stage::AwaitChild;}Child child()const{return child_;}bool resume(Child c){if(!awaitingChild()||child_!=c)return false;stage_=c==Child::ClearHeld?Stage::BindPart:c==Child::Release?Stage::AllNotesOff:Stage::Return;return true;}bool advance(){switch(stage_){case Stage::ClearHeld:request(Child::ClearHeld);break;case Stage::BindPart:stage_=Stage::Release;break;case Stage::Release:request(Child::Release);break;case Stage::AllNotesOff:request(Child::AllNotesOff);break;case Stage::Return:stage_=Stage::Complete;break;case Stage::AwaitChild:case Stage::Complete:return false;}return true;}private:void request(Child c){child_=c;stage_=Stage::AwaitChild;}Stage stage_=Stage::ClearHeld;Child child_=Child::ClearHeld;
};
class MidiAllNotesOffTask final {
public:enum class Stage:uint8_t {Save,Bind,ReadChannel,AddStatus,SendStatus,BindControl,SendControl,ClearValue,SendValue,Restore,Return,AwaitChild,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaitingChild()const{return stage_==Stage::AwaitChild;}bool resume(){if(!awaitingChild())return false;stage_=next_;return true;}template<class R>bool advance(R&&r){switch(stage_){case Stage::Save:stage_=Stage::Bind;break;case Stage::Bind:stage_=Stage::ReadChannel;break;case Stage::ReadChannel:r();stage_=Stage::AddStatus;break;case Stage::AddStatus:stage_=Stage::SendStatus;break;case Stage::SendStatus:request(Stage::BindControl);break;case Stage::BindControl:stage_=Stage::SendControl;break;case Stage::SendControl:request(Stage::ClearValue);break;case Stage::ClearValue:stage_=Stage::SendValue;break;case Stage::SendValue:request(Stage::Restore);break;case Stage::Restore:stage_=Stage::Return;break;case Stage::Return:stage_=Stage::Complete;break;case Stage::AwaitChild:case Stage::Complete:return false;}return true;}private:void request(Stage s){next_=s;stage_=Stage::AwaitChild;}Stage stage_=Stage::Save,next_=Stage::Return;
};
}
